CREATE TABLE IF NOT EXISTS vault_core_varian_wajib (variant_id INT PRIMARY KEY,game_code VARCHAR(20) NOT NULL,nama_game VARCHAR(50) NOT NULL,kategori_produk VARCHAR(40) NOT NULL,jenis_varian VARCHAR(120) NOT NULL,status_audit VARCHAR(120) NOT NULL,temuan_audit TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS vault_core_pertanyaan_wajib_only (pertanyaan_id INT PRIMARY KEY,variant_id INT NOT NULL REFERENCES vault_core_varian_wajib(variant_id) ON DELETE CASCADE,urutan_pertanyaan INT NOT NULL CHECK(urutan_pertanyaan>0),pertanyaan_wajib TEXT NOT NULL,sifat_item VARCHAR(20) NOT NULL DEFAULT 'WAJIB' CHECK(sifat_item='WAJIB'),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(variant_id,urutan_pertanyaan));

INSERT INTO vault_core_varian_wajib(variant_id,game_code,nama_game,kategori_produk,jenis_varian,status_audit,temuan_audit) SELECT (j->>0)::int,j->>1,j->>2,j->>3,j->>4,j->>5,j->>6 FROM jsonb_array_elements($$[[1,"MLBB","Mobile Legends (MLBB)","Akun","Akun MLBB (Polos, Low, Mid, High / Sultan)","PERLU PENYESUAIAN (DIBUANG SARAN 'DISARANKAN MOONTON' & DITAMBAHKAN HARGA/STOK)","Versi sebelumnya memuat saran ('disarankan Moonton') dan belum mencantumkan 'Harga & stok' secara eksplisit sebagai item wajib form dagangan; selain itu frasa 'akun random' dipertegas sebagai larangan syarat wajib."],[2,"MLBB","Mobile Legends (MLBB)","Jasa Joki","Joki Rank (Warrior hingga Mythical Immortal)","SESUAI (HANYA WAJIB, TANPA SARAN)","Seluruh 4 item merupakan syarat/isian wajib kategori Joki Vault Core (moderasi Joki aktif & jadwal dan kapasitas tenaga operasional internal Vault Core yang ditetapkan Owner, jenis/target & durasi pengerjaan, harga & stok, serta data login pembeli & bukti penyelesaian)."],[3,"MLBB","Mobile Legends (MLBB)","Jasa Joki","Joki Classic / Winrate / MCL / Magic Chess","SESUAI (HANYA WAJIB, TANPA SARAN)","Seluruh 4 item merupakan isian/syarat wajib kategori Joki Vault Core tanpa memuat saran."],[4,"FF","Free Fire (FF)","Akun","Akun Free Fire (Old, Sultan, Polos)","SESUAI (HANYA WAJIB, TANPA SARAN)","Seluruh 4 item merupakan isian/syarat wajib jual akun FF di Vault Core (login & bind terkait, data pendukung retrieval & garansi/penahanan dana 30 hari, spesifikasi & screenshot aktual, serta harga & stok)."],[5,"FF","Free Fire (FF)","Jasa Joki","Joki Rank Battle Royale (BR) & Clash Squad (CS)","SESUAI (HANYA WAJIB, TANPA SARAN)","Seluruh 4 item merupakan isian/syarat wajib kategori Joki Vault Core tanpa memuat saran."],[6,"ROBLOX","Roblox","Item In-Game","Item & Fruit Blox Fruits (Permanent Fruit, Gamepass, Physical)","SESUAI (HANYA WAJIB, TANPA SARAN)","Seluruh 3 item merupakan isian wajib dagangan item in-game Roblox (nama item/fruit & map + spesifikasi, harga & stok, serta metode trade/gift & bukti transaksi)."],[7,"ROBLOX","Roblox","Item In-Game","Pet & Item (Adopt Me, Pet Simulator 99, MM2, TTD)","PERBAIKI PENOMORAN (SEBELUMNYA TERCATAT '3.' DUA KALI)","Pada rekap sebelumnya terdapat duplikasi nomor urut '3.' pada item ketiga; penomoran dirapikan menjadi 1, 2, 3 tanpa saran."],[8,"ROBLOX","Roblox","Akun","Akun Roblox (Polos, Korblox, Headless, Akun Map Spesifik)","PERLU PENYESUAIAN (DITAMBAHKAN SYARAT WAJIB RETRIEVAL/GARANSI/PENAHANAN DANA 30 HARI AKUN)","Untuk kategori Akun di Vault Core, selain data login & akses terkait, spesifikasi/screenshot aktual, dan harga & stok, juga berlaku ketentuan data pendukung retrieval akun serta komitmen garansi/penahanan dana 30 hari."],[9,"ROBLOX","Roblox","Jasa Joki","Joki Level, Raid, Awakening, Farming Item/Beli","SESUAI (HANYA WAJIB, TANPA SARAN)","Seluruh 4 item merupakan isian/syarat wajib kategori Joki Vault Core tanpa memuat saran."],[10,"GI","Genshin Impact","Akun","Akun Genshin Impact (Starter Reroll, Mid, End-Game)","PERLU PENYESUAIAN (DIBUANG FRASA OPSIONAL 'JIKA ADA' PADA BUKTI TOP UP TERAKHIR)","Frasa 'jika ada' pada bukti top up terakhir bersifat kondisional/opsional; disederhanakan menjadi pernyataan wajib data pendukung retrieval akun (level/AR, tanggal pembuatan akun, screenshot halaman akun/karakter, serta bukti top up terakhir) & komitmen garansi/penahanan dana 30 hari."],[11,"GI","Genshin Impact","Jasa Joki","Joki Rawat Akun (Daily Commission, Resin, Event)","SESUAI (HANYA WAJIB, TANPA SARAN)","Seluruh 4 item merupakan isian/syarat wajib kategori Joki Vault Core tanpa memuat saran."],[12,"GI","Genshin Impact","Jasa Joki","Joki Eksplorasi Map, Quest Archon/World, Spiral Abyss","SESUAI (HANYA WAJIB, TANPA SARAN)","Seluruh 4 item merupakan isian/syarat wajib kategori Joki Vault Core tanpa memuat saran."]]$$::jsonb) j ON CONFLICT(variant_id) DO UPDATE SET game_code=EXCLUDED.game_code,nama_game=EXCLUDED.nama_game,kategori_produk=EXCLUDED.kategori_produk,jenis_varian=EXCLUDED.jenis_varian,status_audit=EXCLUDED.status_audit,temuan_audit=EXCLUDED.temuan_audit;

INSERT INTO vault_core_pertanyaan_wajib_only(pertanyaan_id,variant_id,urutan_pertanyaan,pertanyaan_wajib,sifat_item) SELECT (j->>0)::int,(j->>1)::int,(j->>2)::int,j->>3,'WAJIB' FROM jsonb_array_elements($$[[1,1,1,"Data login akun (username/email & password) dan data akun sosial media/bind yang terkait"],[2,1,2,"Informasi status bind akun (bukan akun random dan tidak memiliki bind sosmed non-aktif/hilang)"],[3,1,3,"Data pendukung retrieval akun serta komitmen garansi & penahanan dana 30 hari"],[4,1,4,"Spesifikasi akun & bukti gambar/screenshot sesuai kondisi aktual"],[5,1,5,"Harga dagangan & stok"],[6,2,1,"Status moderasi Joki aktif & jadwal/kapasitas tenaga operasional internal Vault Core yang ditetapkan Owner"],[7,2,2,"Jenis & target joki rank beserta durasi pengerjaan"],[8,2,3,"Harga dagangan & stok"],[9,2,4,"Data login akun pembeli untuk pengerjaan & bukti penyelesaian pesanan"],[10,3,1,"Status moderasi Joki aktif & jadwal/kapasitas tenaga operasional internal Vault Core yang ditetapkan Owner"],[11,3,2,"Jenis joki (Classic / Winrate / MCL / Magic Chess) & target pesanan beserta durasi pengerjaan"],[12,3,3,"Harga dagangan & stok"],[13,3,4,"Data login akun pembeli & bukti penyelesaian pesanan"],[14,4,1,"Data login akun (email/username & password) beserta data akun sosial media terkait (Google/Facebook)"],[15,4,2,"Kelengkapan data pendukung retrieval akun serta komitmen garansi & penahanan dana 30 hari"],[16,4,3,"Spesifikasi akun & bukti gambar/screenshot sesuai kondisi aktual (bukan random)"],[17,4,4,"Harga dagangan & stok"],[18,5,1,"Status moderasi Joki aktif & jadwal/kapasitas tenaga operasional internal Vault Core yang ditetapkan Owner"],[19,5,2,"Mode rank (BR / CS) & target tier beserta durasi pengerjaan"],[20,5,3,"Harga dagangan & stok"],[21,5,4,"Data login akun pembeli & bukti penyelesaian pesanan"],[22,6,1,"Nama item/fruit & map Roblox serta spesifikasi item"],[23,6,2,"Harga dagangan & stok"],[24,6,3,"Metode pengiriman trade/gift in-game & bukti pengiriman/transaksi"],[25,7,1,"Nama pet/item & map Roblox serta spesifikasi item"],[26,7,2,"Harga dagangan & stok"],[27,7,3,"Metode pengiriman trade in-game & bukti pengiriman/transaksi"],[28,8,1,"Data login akun (username/email & password) beserta akses/data akun terkait"],[29,8,2,"Data pendukung retrieval akun serta komitmen garansi & penahanan dana 30 hari"],[30,8,3,"Spesifikasi akun & bukti gambar/screenshot sesuai kondisi aktual (bukan random)"],[31,8,4,"Harga dagangan & stok"],[32,9,1,"Status moderasi Joki aktif & jadwal/kapasitas tenaga operasional internal Vault Core yang ditetapkan Owner"],[33,9,2,"Map & jenis joki (level/raid/awakening/farming) beserta durasi pengerjaan"],[34,9,3,"Harga dagangan & stok"],[35,9,4,"Data login akun pembeli & bukti penyelesaian pesanan"],[36,10,1,"Data login akun & data email/akun sosial media yang terkait pada akun Genshin Impact"],[37,10,2,"Data pendukung retrieval akun (level/AR, tanggal pembuatan akun, screenshot halaman akun/karakter, bukti top up terakhir) serta komitmen garansi & penahanan dana 30 hari"],[38,10,3,"Spesifikasi akun & bukti gambar/screenshot sesuai kondisi aktual"],[39,10,4,"Harga dagangan & stok"],[40,11,1,"Status moderasi Joki aktif & jadwal/kapasitas tenaga operasional internal Vault Core yang ditetapkan Owner"],[41,11,2,"Rincian & durasi paket rawat akun (daily commission/resin/event) beserta durasi pengerjaan"],[42,11,3,"Harga dagangan & stok"],[43,11,4,"Data login akun pembeli & bukti penyelesaian pesanan"],[44,12,1,"Status moderasi Joki aktif & jadwal/kapasitas tenaga operasional internal Vault Core yang ditetapkan Owner"],[45,12,2,"Jenis & target joki (eksplorasi map/quest/Spiral Abyss) beserta durasi pengerjaan"],[46,12,3,"Harga dagangan & stok"],[47,12,4,"Data login akun pembeli & bukti penyelesaian pesanan"]]$$::jsonb) j ON CONFLICT(pertanyaan_id) DO UPDATE SET variant_id=EXCLUDED.variant_id,urutan_pertanyaan=EXCLUDED.urutan_pertanyaan,pertanyaan_wajib=EXCLUDED.pertanyaan_wajib,sifat_item='WAJIB';

CREATE OR REPLACE VIEW vw_vault_core_audit_pertanyaan_wajib_owner AS SELECT v.variant_id,v.nama_game,v.kategori_produk,v.jenis_varian,v.status_audit,COUNT(q.pertanyaan_id) AS jumlah_pertanyaan_wajib,STRING_AGG(q.urutan_pertanyaan::text||'. '||q.pertanyaan_wajib,' | ' ORDER BY q.urutan_pertanyaan) AS daftar_pertanyaan_wajib FROM vault_core_varian_wajib v LEFT JOIN vault_core_pertanyaan_wajib_only q ON q.variant_id=v.variant_id GROUP BY v.variant_id,v.nama_game,v.kategori_produk,v.jenis_varian,v.status_audit;

ALTER TABLE products ADD COLUMN IF NOT EXISTS variant_id INT;

ALTER TABLE products ADD COLUMN IF NOT EXISTS variant_subtype TEXT;

DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='products_variant_id_fkey' AND conrelid='public.products'::regclass) THEN ALTER TABLE products ADD CONSTRAINT products_variant_id_fkey FOREIGN KEY(variant_id) REFERENCES vault_core_varian_wajib(variant_id) ON DELETE RESTRICT; END IF; END $$;

CREATE INDEX IF NOT EXISTS idx_products_variant_status ON products(variant_id,status);

CREATE TABLE IF NOT EXISTS vault_core_product_question_responses(product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE,question_id INT NOT NULL REFERENCES vault_core_pertanyaan_wajib_only(pertanyaan_id) ON DELETE RESTRICT,response_text TEXT NOT NULL DEFAULT '',proof_urls JSONB NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(proof_urls)='array' AND jsonb_array_length(proof_urls)<=8),response_status TEXT NOT NULL DEFAULT 'PENDING' CHECK(response_status IN ('PENDING','ANSWERED','OWNER_VERIFIED','SECRET_IN_VAULT')),created_by_telegram_id BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(product_id,question_id));

CREATE TABLE IF NOT EXISTS vault_core_secret_payloads(id BIGSERIAL PRIMARY KEY,secret_scope TEXT NOT NULL CHECK(secret_scope IN ('PRODUCT_ACCOUNT','JOKI_CUSTOMER_ACCESS')),product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,inventory_item_id BIGINT REFERENCES inventory_items(id) ON DELETE RESTRICT,order_id BIGINT REFERENCES orders(id) ON DELETE RESTRICT,order_item_id BIGINT REFERENCES order_items(id) ON DELETE RESTRICT,customer_id BIGINT REFERENCES customers(id) ON DELETE RESTRICT,payload_ciphertext BYTEA,payload_nonce BYTEA,payload_auth_tag BYTEA,wrapped_data_key BYTEA,key_wrap_nonce BYTEA,key_wrap_auth_tag BYTEA,encryption_key_version SMALLINT NOT NULL CHECK(encryption_key_version>0),secret_status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(secret_status IN ('ACTIVE','REVOKED','DESTROYED')),retention_expires_at TIMESTAMPTZ,created_by_telegram_id BIGINT NOT NULL,last_accessed_at TIMESTAMPTZ,destroyed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT chk_vc_secret_scope_links CHECK((secret_scope='PRODUCT_ACCOUNT' AND inventory_item_id IS NOT NULL AND ((order_id IS NULL AND order_item_id IS NULL AND customer_id IS NULL) OR (order_id IS NOT NULL AND order_item_id IS NOT NULL AND customer_id IS NOT NULL))) OR (secret_scope='JOKI_CUSTOMER_ACCESS' AND inventory_item_id IS NULL AND order_id IS NOT NULL AND order_item_id IS NOT NULL AND customer_id IS NOT NULL)),CONSTRAINT chk_vc_secret_cipher_bundle CHECK((secret_status IN ('ACTIVE','REVOKED') AND payload_ciphertext IS NOT NULL AND octet_length(payload_ciphertext)>0 AND payload_nonce IS NOT NULL AND octet_length(payload_nonce)=12 AND payload_auth_tag IS NOT NULL AND octet_length(payload_auth_tag)=16 AND wrapped_data_key IS NOT NULL AND octet_length(wrapped_data_key)>0 AND key_wrap_nonce IS NOT NULL AND octet_length(key_wrap_nonce)=12 AND key_wrap_auth_tag IS NOT NULL AND octet_length(key_wrap_auth_tag)=16 AND destroyed_at IS NULL) OR (secret_status='DESTROYED' AND payload_ciphertext IS NULL AND payload_nonce IS NULL AND payload_auth_tag IS NULL AND wrapped_data_key IS NULL AND key_wrap_nonce IS NULL AND key_wrap_auth_tag IS NULL AND destroyed_at IS NOT NULL)));

CREATE UNIQUE INDEX IF NOT EXISTS ux_vc_secret_active_product_account ON vault_core_secret_payloads(inventory_item_id) WHERE secret_scope='PRODUCT_ACCOUNT' AND secret_status='ACTIVE';

CREATE UNIQUE INDEX IF NOT EXISTS ux_vc_secret_active_joki_order_item ON vault_core_secret_payloads(order_item_id) WHERE secret_scope='JOKI_CUSTOMER_ACCESS' AND secret_status='ACTIVE';

CREATE INDEX IF NOT EXISTS idx_vc_secret_product ON vault_core_secret_payloads(product_id,secret_status);

CREATE INDEX IF NOT EXISTS idx_vc_secret_order_customer ON vault_core_secret_payloads(order_id,customer_id,secret_status);

CREATE INDEX IF NOT EXISTS idx_vc_secret_retention ON vault_core_secret_payloads(secret_status,retention_expires_at);

CREATE OR REPLACE FUNCTION vault_core_validate_secret_payload_links() RETURNS TRIGGER LANGUAGE plpgsql AS $$ DECLARE vip BIGINT; oip BIGINT; oid BIGINT; ocid BIGINT; BEGIN IF NEW.secret_scope='PRODUCT_ACCOUNT' THEN SELECT product_id INTO vip FROM inventory_items WHERE id=NEW.inventory_item_id; IF NOT FOUND OR vip<>NEW.product_id THEN RAISE EXCEPTION 'VAULT_SECRET_INVENTORY_PRODUCT_MISMATCH' USING ERRCODE='23514'; END IF; END IF; IF NEW.order_item_id IS NOT NULL THEN SELECT oi.product_id,oi.order_id,o.customer_id INTO oip,oid,ocid FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.id=NEW.order_item_id; IF NOT FOUND OR oip<>NEW.product_id OR oid<>NEW.order_id OR ocid<>NEW.customer_id THEN RAISE EXCEPTION 'VAULT_SECRET_ORDER_CONTEXT_MISMATCH' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;

DROP TRIGGER IF EXISTS trg_vc_secret_payload_links ON vault_core_secret_payloads;

CREATE TRIGGER trg_vc_secret_payload_links BEFORE INSERT OR UPDATE OF secret_scope,product_id,inventory_item_id,order_id,order_item_id,customer_id ON vault_core_secret_payloads FOR EACH ROW EXECUTE FUNCTION vault_core_validate_secret_payload_links();

CREATE TABLE IF NOT EXISTS vault_core_secret_access_logs(id BIGSERIAL PRIMARY KEY,secret_payload_id BIGINT NOT NULL REFERENCES vault_core_secret_payloads(id) ON DELETE RESTRICT,actor_telegram_user_id BIGINT NOT NULL,action TEXT NOT NULL CHECK(action IN ('CREATE','READ','UPDATE','REVOKE','DESTROY','DELIVER')),reason TEXT NOT NULL CHECK(length(btrim(reason)) BETWEEN 3 AND 500),request_reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX IF NOT EXISTS idx_vc_secret_access_history ON vault_core_secret_access_logs(secret_payload_id,created_at DESC);

CREATE INDEX IF NOT EXISTS idx_vc_secret_access_actor ON vault_core_secret_access_logs(actor_telegram_user_id,created_at DESC);

CREATE OR REPLACE FUNCTION vault_core_block_secret_access_log_mutation() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'VAULT_SECRET_ACCESS_LOG_IS_APPEND_ONLY' USING ERRCODE='55000'; END $$;

DROP TRIGGER IF EXISTS trg_vc_secret_access_log_append_only ON vault_core_secret_access_logs;

CREATE TRIGGER trg_vc_secret_access_log_append_only BEFORE UPDATE OR DELETE ON vault_core_secret_access_logs FOR EACH ROW EXECUTE FUNCTION vault_core_block_secret_access_log_mutation();

REVOKE ALL ON TABLE vault_core_secret_payloads FROM PUBLIC;

REVOKE ALL ON TABLE vault_core_secret_access_logs FROM PUBLIC;
